#!/usr/bin/env python3\n"""Deterministic AFAGHX engineering-control-plane runtime."""\nfrom __future__ import annotations\nimport hashlib, json, subprocess\nfrom pathlib import Path\nROOT = Path(__file__).resolve().parents[2]\nOUT = ROOT / "agent-evidence"\nOUT.mkdir(exist_ok=True)\ndef run(*args: str) -> str:\n    p = subprocess.run(args, cwd=ROOT, text=True, capture_output=True, check=False)\n    return p.stdout.strip()\ndef exists(path: str) -> bool:\n    return (ROOT / path).is_file()\nbaseline = run("git", "rev-parse", "HEAD")\ntracked_files = run("git", "ls-files").splitlines()\nrequired = ["AGENTS.md", ".ai/command-center.yaml", ".ai/agents/afaghx-chief-engineering-agent.md", ".ai/policies/engineering.md", ".ai/evidence/evidence-schema.yaml"]\narchitecture = {"canonical_repo":"afaghx-afaghx/platform","canonical_api":"https://api.afaghx.com","canonical_runtime":"Gateway -> PersistentAfxCore -> PostgreSQL","experience_boundary":"presentation-only"}\nauth_paths = [p for p in tracked_files if any(k in p.lower() for k in ("auth","security-boundary","persistent-core","repository"))]\nforbidden = [p for p in tracked_files if p == ".env" or p.startswith(".env.") or p.endswith((".pem", ".key")) or p.endswith("/id_rsa")]\nhashes = {}\nfor p in required:\n    if exists(p): hashes[p] = hashlib.sha256((ROOT/p).read_bytes()).hexdigest()\nresult = {\n  "schema_version":"AFX-AI-CEA-EVIDENCE-1", "agent_id":"AFX-AI-CEA-001", "truth_state":"TESTED", "baseline_sha":baseline,\n  "repository_inventory":{"tracked_file_count":len(tracked_files),"required_control_plane_files_present":all(exists(p) for p in required),"required_file_hashes":hashes},\n  "architecture_boundary_check":architecture, "authentication_surface_inventory":sorted(auth_paths),\n  "security_gate_results":{"tracked_secret_like_files":forbidden,"secret_like_files_present":len(forbidden)==0,"git_diff_check":run("git","diff","--check")==""},\n  "governance":{"main_branch_write_by_runtime":False,"production_deploy_by_runtime":False,"merge_authority":"human"},\n  "classification_policy":["KEEP","REFACTOR","REPLACE","REMOVE","FREEZE","ADD"], "unknown_is_not_green":True}\n(OUT/"forensics.json").write_text(json.dumps(result,indent=2,ensure_ascii=False)+"\n")\n(OUT/"baseline-sha.txt").write_text(baseline+"\n")\n(OUT/"forensics.md").write_text("# AFAGHX Chief Engineering Agent — Deterministic Runtime Evidence\n\n"+f"- Baseline SHA: {baseline}\n- Truth state: {result['truth_state']}\n- Required control-plane files present: {result['repository_inventory']['required_control_plane_files_present']}\n- Secret-like tracked files detected: {len(forbidden)}\n- AI/model reasoning: NOT REQUIRED FOR THIS DETERMINISTIC GATE\n- Unknown evidence remains UNKNOWN; no synthetic GREEN.\n")\nprint(json.dumps(result,indent=2,ensure_ascii=False))\n